// Biblioteca de DDS: 150 temas com texto curto para o ministrante ler ou adaptar
// e uma pergunta para abrir a conversa com a equipe (DDS vivencial).
export type TemaDds = { categoria: string; tema: string; conteudo: string; pergunta: string };

export const TEMAS_DDS: TemaDds[] = [
  { categoria: "EPI e uniforme", tema: "Por que usar o EPI", conteudo: "O EPI é a última barreira entre você e o risco. Ele só protege se estiver em bom estado, no tamanho certo e sendo usado durante todo o tempo de exposição. Se o seu EPI estiver danificado, desconfortável ou faltando, avise o supervisor antes de começar o trabalho. Usar o EPI é obrigação do trabalhador, e fornecer o EPI adequado é obrigação da empresa.", pergunta: "Qual EPI você mais esquece ou acha incômodo de usar? Por quê?" },
  { categoria: "Ordem e limpeza", tema: "Ordem e limpeza", conteudo: "Um ambiente arrumado evita tropeços, quedas, cortes e incêndios. Cada ferramenta tem o seu lugar, e corredores e saídas de emergência precisam ficar livres. Limpe o que sujar na hora, principalmente óleo e água no piso. Lixo e retalhos vão para o local certo, separados quando houver coleta seletiva.", pergunta: "O que está fora do lugar no nosso setor agora?" },
  { categoria: "Ergonomia", tema: "Levantamento manual de cargas", conteudo: "Antes de levantar, avalie o peso e peça ajuda ou use um equipamento se for preciso. Aproxime-se da carga, dobre os joelhos e mantenha as costas retas, levantando com a força das pernas. Mantenha a carga perto do corpo e não gire o tronco: vire com os pés. Planeje o caminho antes, para não carregar peso por cima de obstáculos.", pergunta: "Qual é a carga mais pesada que você levanta no seu dia?" },
  { categoria: "Comportamento seguro", tema: "Quase acidente: por que relatar", conteudo: "Quase acidente é o que quase machucou alguém. Para cada acidente grave, acontecem muitos quase acidentes antes, e cada um é um aviso. Relatar não é dedurar: é dar a chance de corrigir a causa antes que alguém se machuque. Conte o que aconteceu, onde e como, e sugira o que poderia ser feito.", pergunta: "Você se lembra de um quase acidente recente? O que poderia ter sido feito?" },
  { categoria: "Incêndio e emergência", tema: "Prevenção de incêndio", conteudo: "O fogo precisa de três coisas: combustível, oxigênio e calor. Prevenir é separar essas três. Não sobrecarregue tomadas, não fume fora das áreas permitidas e guarde inflamáveis em local ventilado e identificado. Saiba onde ficam os extintores e as saídas de emergência, e nunca deixe materiais na frente deles.", pergunta: "Onde fica o extintor mais próximo de onde você está?" },
  { categoria: "Incêndio e emergência", tema: "Uso de extintores", conteudo: "Cada classe de fogo pede um extintor: classe A para madeira, papel e tecido; classe B para líquidos inflamáveis; classe C para equipamentos elétricos energizados. Para usar: retire a trava, aponte para a base das chamas, aperte o gatilho e faça movimentos de varredura. Se o fogo não ceder em poucos segundos, saia e acione a brigada.", pergunta: "Quem aqui já usou um extintor de verdade?" },
  { categoria: "Eletricidade", tema: "Riscos da eletricidade", conteudo: "Só pessoas autorizadas mexem em instalações elétricas. Nunca use fios emendados, plugues quebrados ou extensões improvisadas. Mantenha painéis fechados e não coloque objetos na frente deles. Se ver um fio desencapado ou sentir choque em um equipamento, desligue se for seguro, isole a área e avise a manutenção.", pergunta: "Tem alguma tomada, fio ou plugue danificado no seu posto?" },
  { categoria: "Trabalho em altura", tema: "Trabalho em altura", conteudo: "Trabalho em altura é qualquer atividade acima de 2 metros do nível inferior onde haja risco de queda. Só faz quem é treinado e está apto no exame médico. O cinto paraquedista precisa estar ancorado em ponto seguro o tempo todo. Escadas devem estar firmes e ultrapassar 1 metro o ponto de apoio. Na dúvida, pare e chame o responsável.", pergunta: "Qual atividade daqui é feita acima de 2 metros?" },
  { categoria: "EPI e uniforme", tema: "Proteção das mãos", conteudo: "As mãos são as partes do corpo mais atingidas em acidentes. Use a luva certa para cada risco: corte, calor, produto químico ou eletricidade. Nunca coloque as mãos em partes móveis de máquinas sem desligar e bloquear. Não use anéis, pulseiras e relógios perto de máquinas.", pergunta: "Você já machucou as mãos no trabalho? Como foi?" },
  { categoria: "Ruído e vibração", tema: "Proteção auditiva", conteudo: "A perda de audição por ruído é lenta, não dói e não tem volta. Se você precisa gritar para conversar com alguém a um braço de distância, o ruído provavelmente está alto. Use o protetor auditivo durante todo o tempo de exposição, coloque com as mãos limpas e guarde no estojo. Protetor que fica no bolso não protege.", pergunta: "Você usa o protetor auricular o tempo todo nas áreas barulhentas?" },
  { categoria: "Produtos químicos", tema: "Produtos químicos", conteudo: "Antes de usar um produto, leia o rótulo e a ficha de segurança (FDS). Nunca troque o produto de embalagem sem identificar, e nunca use garrafas de bebida para guardar químicos. Use as luvas, óculos e máscara indicados. Não misture produtos de limpeza: alguns liberam gases tóxicos. Em contato com a pele ou os olhos, lave com muita água.", pergunta: "Qual produto químico você usa e o que diz o rótulo dele?" },
  { categoria: "Ergonomia", tema: "Ergonomia no posto de trabalho", conteudo: "Ajuste a cadeira para que os pés fiquem apoiados e os joelhos em ângulo reto. A tela deve ficar na altura dos olhos, a um braço de distância. Faça pausas curtas para alongar e mudar de posição. Se sentir dor que se repete, não espere piorar: comunique o supervisor ou o serviço de saúde.", pergunta: "Seu posto está ajustado para o seu corpo?" },
  { categoria: "Máquinas e ferramentas", tema: "Máquinas e equipamentos", conteudo: "Só opere máquinas para as quais você foi treinado e autorizado. Nunca retire ou desative proteções e dispositivos de segurança. Antes de limpar, ajustar ou fazer manutenção, desligue e bloqueie a energia. Conheça a posição do botão de emergência e teste-o no início do turno.", pergunta: "Onde fica o botão de emergência da máquina que você usa?" },
  { categoria: "Saúde e bem-estar", tema: "Saúde mental e estresse", conteudo: "Cansaço, preocupação e estresse tiram a atenção e aumentam o risco de acidente. Durma bem, faça pausas e converse quando algo não estiver bem. Cuidar da saúde mental também é segurança. Se você ou um colega estiver passando por um momento difícil, procure apoio: a empresa e os serviços de saúde podem ajudar.", pergunta: "O que mais causa estresse no nosso trabalho e o que poderia ajudar?" },
  { categoria: "Respeito e convivência", tema: "Assédio no trabalho", conteudo: "Assédio moral é a exposição repetida a humilhações e constrangimentos. Assédio sexual é qualquer conduta de natureza sexual não desejada. Os dois são proibidos e podem ser denunciados pelo canal da empresa ou à CIPA, com garantia de sigilo. Respeito é parte da segurança: todos têm direito a um ambiente de trabalho saudável.", pergunta: "Você sabe onde e como fazer uma denúncia com sigilo?" },
  { categoria: "Comportamento seguro", tema: "Comunicação de acidentes", conteudo: "Todo acidente, por menor que pareça, precisa ser comunicado ao supervisor na hora. Um corte pequeno pode infeccionar, e uma pancada pode ter consequência depois. O registro garante o atendimento, os direitos do trabalhador e a investigação para evitar que se repita.", pergunta: "A quem você comunica um acidente aqui?" },
  { categoria: "Trânsito e transporte", tema: "Trânsito interno e empilhadeiras", conteudo: "Respeite as faixas de pedestres e as áreas demarcadas. Nunca passe por trás ou debaixo da carga de uma empilhadeira. Faça contato visual com o operador antes de cruzar o caminho. Operadores: velocidade baixa, buzina nos cruzamentos e carga sempre baixa durante o deslocamento.", pergunta: "Onde pedestres e veículos se cruzam aqui dentro?" },
  { categoria: "Calor e frio", tema: "Hidratação e calor", conteudo: "Em ambientes quentes, o corpo perde muita água pelo suor. Beba água com frequência, mesmo sem sede. Dor de cabeça, tontura, cãibras e enjoo podem ser sinais de excesso de calor: pare, vá para a sombra e avise o supervisor. Faça pausas em local fresco e use roupas leves quando possível.", pergunta: "Quantos copos de água você já bebeu hoje?" },
  { categoria: "Máquinas e ferramentas", tema: "Ferramentas manuais", conteudo: "Use cada ferramenta só para a função dela: chave de fenda não é talhadeira. Inspecione antes de usar e separe as que estiverem com cabo solto, rachado ou gasto. Guarde as ferramentas no lugar certo e não carregue ferramentas pontiagudas no bolso. Ferramenta boa e bem usada evita cortes e pancadas.", pergunta: "Tem alguma ferramenta aqui com cabo solto ou gasto?" },
  { categoria: "Comportamento seguro", tema: "Atenção e pressa", conteudo: "A pressa é uma das maiores causas de acidente. Quando o prazo aperta, a tentação é pular etapas de segurança. Nenhum serviço é tão urgente que não possa ser feito com segurança. Se perceber que está trabalhando no automático ou distraído, pare um minuto, respire e retome com atenção.", pergunta: "Em que momento do dia a pressa é maior aqui?" },
  { categoria: "EPI e uniforme", tema: "Óculos de proteção", conteudo: "Os olhos se machucam em segundos: uma lasca, um respingo de produto ou poeira podem causar lesão permanente. Use os óculos sempre que houver corte, esmerilhamento, solda, limpeza com produtos ou poeira no ar. Mantenha a lente limpa e sem riscos, e troque quando estiver arranhada ou com a haste solta. Óculos pendurado no pescoço não protege.", pergunta: "Em qual atividade do nosso dia a dia alguém poderia levar um respingo ou uma lasca no olho?" },
  { categoria: "EPI e uniforme", tema: "Calçado de segurança", conteudo: "O calçado de segurança protege contra queda de objetos, perfurações, escorregões e choque elétrico, dependendo do modelo. Ele precisa estar no tamanho certo, amarrado e com o solado em bom estado. Solado liso, biqueira aparecendo ou sola descolando são sinais de troca. Não troque o calçado da empresa por tênis comum, nem por pouco tempo.", pergunta: "Como está o solado do seu calçado hoje? Alguém aqui precisa pedir troca?" },
  { categoria: "EPI e uniforme", tema: "Luvas: a certa para cada risco", conteudo: "Não existe luva para tudo. Luva de raspa protege de abrasão, luva nitrílica de produtos químicos, luva de malha de aço de cortes de faca, e luva isolante de eletricidade. Usar a luva errada dá falsa segurança. Atenção: perto de máquinas com partes girando, a luva pode ser puxada junto com a mão.", pergunta: "Quais luvas usamos aqui e para qual risco serve cada uma?" },
  { categoria: "EPI e uniforme", tema: "Proteção respiratória", conteudo: "Poeiras, fumos, névoas e vapores entram pelo nariz e pela boca sem a gente perceber. A máscara só protege se for a indicada para o agente e se estiver bem ajustada ao rosto: barba atrapalha a vedação. Faça o teste de vedação toda vez que colocar. Troque o filtro no prazo ou quando ficar difícil respirar.", pergunta: "Você sabe qual é o filtro da sua máscara e quando ele deve ser trocado?" },
  { categoria: "EPI e uniforme", tema: "Uniforme e roupas adequadas", conteudo: "Roupas largas, mangas soltas, cordões e cabelos compridos soltos podem ser puxados por máquinas. Use o uniforme fornecido, com as mangas abotoadas, e prenda o cabelo. Em áreas com calor, chama ou eletricidade, a roupa certa também é proteção. Uniforme sujo de produto químico deve ser trocado e lavado separado.", pergunta: "Tem alguma peça do uniforme que atrapalha o seu trabalho ou está gasta?" },
  { categoria: "EPI e uniforme", tema: "Cuidar e guardar o EPI", conteudo: "EPI bem cuidado dura mais e protege melhor. Limpe depois do uso, guarde em local seco e longe de sol e produtos, e não divida protetor auricular ou máscara com colegas. Antes de usar, confira se não há rasgos, trincas ou peças faltando. EPI com defeito deve ser trocado, não improvisado.", pergunta: "Onde cada um guarda o seu EPI no fim do turno?" },
  { categoria: "EPI e uniforme", tema: "CA: o documento do EPI", conteudo: "Todo EPI vendido no Brasil precisa ter o Certificado de Aprovação, o CA, emitido pelo Ministério do Trabalho. O número fica gravado no próprio equipamento ou na embalagem. Sem CA ou com CA vencido, o EPI não deve ser usado. Se você receber um EPI diferente do habitual, confira o CA com a segurança.", pergunta: "Alguém já conferiu o número do CA do EPI que está usando agora?" },
  { categoria: "EPI e uniforme", tema: "Capacete", conteudo: "O capacete protege a cabeça contra impactos e quedas de objetos, e alguns modelos também contra choque elétrico. Use sempre com a jugular presa quando houver risco de queda do capacete, e ajuste a carneira ao tamanho da cabeça. Não pinte, não fure e não guarde o capacete no sol do carro. Depois de uma pancada forte, ele deve ser trocado.", pergunta: "Em quais áreas da empresa o capacete é obrigatório?" },
  { categoria: "Ordem e limpeza", tema: "Programa 5S", conteudo: "O 5S organiza o trabalho em cinco passos: separar o que não serve, arrumar cada coisa no seu lugar, limpar, padronizar e manter a disciplina. Um ambiente organizado reduz acidentes, perda de tempo e retrabalho. Cada um cuida do próprio posto, mas o resultado é de todos. Comece hoje tirando do seu posto o que você não usa.", pergunta: "O que tem no seu posto de trabalho que poderia sair hoje?" },
  { categoria: "Ordem e limpeza", tema: "Piso escorregadio", conteudo: "Água, óleo, farinha, gordura e restos de produto deixam o piso perigoso. Limpou, sinalize. Viu algo derramado, limpe ou isole e avise na hora. Use o calçado indicado e não corra nos corredores. Muitos acidentes graves começam com um simples escorregão.", pergunta: "Onde o piso costuma ficar molhado ou escorregadio aqui?" },
  { categoria: "Ordem e limpeza", tema: "Empilhamento de materiais", conteudo: "Pilhas altas, tortas ou apoiadas em paredes podem desabar. Empilhe sempre o mais pesado embaixo, respeite a altura máxima indicada e deixe espaço para circulação. Não empilhe na frente de extintores, quadros elétricos, saídas ou chuveiros de emergência. Pilha instável deve ser desfeita e montada de novo.", pergunta: "Tem alguma pilha de material aqui que te preocupa?" },
  { categoria: "Ordem e limpeza", tema: "Corredores e saídas livres", conteudo: "Em uma emergência, cada segundo conta. Corredores, escadas e portas de saída precisam estar sempre livres, sem caixas, carrinhos ou materiais. A porta de emergência não pode ficar trancada durante o expediente. Se encontrar uma saída bloqueada, avise imediatamente.", pergunta: "Se faltasse luz agora, você saberia chegar à saída mais próxima?" },
  { categoria: "Ordem e limpeza", tema: "Descarte correto de resíduos", conteudo: "Cada resíduo tem o seu destino: comum, reciclável, contaminado com óleo ou produto, perfurocortante e eletrônico. Misturar resíduos pode causar acidente, contaminação e multa para a empresa. Vidro quebrado e lâminas vão embalados e identificados, para não cortar quem recolhe o lixo. Na dúvida, pergunte antes de descartar.", pergunta: "Quais tipos de lixo geramos aqui e onde vai cada um?" },
  { categoria: "Ordem e limpeza", tema: "Fim de turno organizado", conteudo: "Deixar o posto arrumado no fim do turno é cuidar de quem chega depois. Desligue equipamentos, guarde ferramentas, recolha restos de material e avise sobre qualquer problema encontrado. Passar o turno com informação clara evita acidentes de quem não sabia que algo estava com defeito.", pergunta: "O que é importante você contar para quem pega o turno depois de você?" },
  { categoria: "Ergonomia", tema: "Trabalho em pé por muito tempo", conteudo: "Ficar muitas horas em pé cansa as pernas, a coluna e favorece varizes. Sempre que possível, alterne o apoio dos pés, use o apoio para pés ou banqueta quando houver e faça pequenas pausas para caminhar. O calçado confortável e o tapete antifadiga ajudam. Se as dores se repetem, comunique.", pergunta: "No fim do dia, onde você sente mais cansaço no corpo?" },
  { categoria: "Ergonomia", tema: "Movimentos repetitivos", conteudo: "Repetir o mesmo movimento muitas vezes por dia pode inflamar tendões e articulações, causando dor nos punhos, cotovelos e ombros. Faça as pausas previstas, alterne tarefas quando der e mantenha os punhos em posição neutra. Formigamento e dor que piora à noite são sinais de alerta: procure o serviço de saúde cedo.", pergunta: "Qual tarefa aqui exige o mesmo movimento muitas vezes seguidas?" },
  { categoria: "Ergonomia", tema: "Alongamento antes do trabalho", conteudo: "Músculo frio se machuca mais fácil. Alguns minutos de alongamento antes de começar e nas pausas preparam o corpo e aliviam a tensão. Alongue devagar, sem forçar até doer, e respire normalmente. Hoje vamos fazer juntos um alongamento de pescoço, ombros, punhos e pernas.", pergunta: "Qual parte do corpo você sente mais tensa no começo do turno?" },
  { categoria: "Ergonomia", tema: "Empurrar e puxar carrinhos", conteudo: "Empurrar é melhor do que puxar: você enxerga o caminho e usa a força das pernas. Confira se as rodinhas estão boas e se o carrinho não está carregado demais. Não carregue tanto a ponto de não ver por cima da carga. Em rampas, peça ajuda e controle a velocidade.", pergunta: "Tem algum carrinho aqui com roda ruim ou difícil de manobrar?" },
  { categoria: "Ergonomia", tema: "Uso do celular e postura", conteudo: "Olhar o celular com a cabeça baixa por muito tempo sobrecarrega o pescoço. Nas pausas, prefira levantar, caminhar e descansar a vista. Durante o trabalho, celular na mão tira a atenção e pode causar acidente, principalmente perto de máquinas e em circulação de veículos.", pergunta: "Já aconteceu de alguém se distrair com o celular e quase se machucar?" },
  { categoria: "Incêndio e emergência", tema: "Plano de abandono", conteudo: "Quando o alarme tocar, pare o que está fazendo, desligue o equipamento se for seguro e siga a rota de fuga até o ponto de encontro. Não use elevador, não volte para pegar objetos e ajude quem tem dificuldade. No ponto de encontro, fique até ser liberado, para que ninguém seja dado como desaparecido.", pergunta: "Onde fica o nosso ponto de encontro?" },
  { categoria: "Incêndio e emergência", tema: "Gás de cozinha (GLP)", conteudo: "O GLP é mais pesado que o ar e se acumula perto do chão. Cheiro de gás: não acenda luz, não ligue aparelhos, feche o registro, abra portas e janelas e saia do local. Botijões ficam em local ventilado, fora do prédio quando possível, em pé e protegidos. Teste vazamento só com espuma de sabão, nunca com fogo.", pergunta: "Você sabe onde fica o registro de gás do nosso setor?" },
  { categoria: "Incêndio e emergência", tema: "Brigada de emergência", conteudo: "A brigada é formada por colegas treinados para agir nos primeiros minutos de uma emergência: combate ao princípio de incêndio, primeiros socorros e abandono. Saiba quem são os brigadistas do seu setor e como chamá-los. Em uma emergência, siga as orientações da brigada.", pergunta: "Quem são os brigadistas do nosso turno?" },
  { categoria: "Incêndio e emergência", tema: "Números de emergência", conteudo: "Bombeiros 193, SAMU 192, Polícia 190. Ao ligar, diga com calma o que aconteceu, o endereço completo com ponto de referência, quantas vítimas e o estado delas. Não desligue até o atendente orientar. Deixe alguém esperando o socorro na entrada para mostrar o caminho.", pergunta: "Qual é o endereço completo da empresa para passar ao socorro?" },
  { categoria: "Incêndio e emergência", tema: "Princípio de incêndio", conteudo: "Ao ver fogo, dê o alarme primeiro. Só tente apagar se o fogo for pequeno, se você souber usar o extintor e se tiver uma saída livre às suas costas. Se a fumaça aumentar, saia abaixado, perto do chão, onde o ar é mais limpo. Feche as portas ao sair para segurar o fogo.", pergunta: "Se você visse fogo agora, qual seria a primeira coisa a fazer?" },
  { categoria: "Incêndio e emergência", tema: "Sinalização de emergência", conteudo: "As placas fotoluminescentes de saída, extintor e hidrante brilham no escuro justamente para guiar em uma emergência com falta de luz. Elas não podem ser tapadas por cartazes, caixas ou prateleiras. Iluminação de emergência deve acender sozinha quando a energia cai: se não acender, avise a manutenção.", pergunta: "Tem alguma placa de emergência aqui escondida ou apagada?" },
  { categoria: "Eletricidade", tema: "Extensões e benjamins", conteudo: "Extensão improvisada e benjamim com vários aparelhos sobrecarregam a tomada, esquentam e podem pegar fogo. Use extensão adequada, sem emendas, e só pelo tempo necessário. Nunca passe fio por baixo de tapete ou porta, onde ele é amassado. Aparelho que esquenta muito a tomada deve ir para a manutenção.", pergunta: "Tem alguma tomada aqui com muita coisa ligada ao mesmo tempo?" },
  { categoria: "Eletricidade", tema: "Choque elétrico: como socorrer", conteudo: "Nunca toque na vítima de choque enquanto ela estiver em contato com a energia: você também leva o choque. Desligue a chave geral ou afaste o fio com material seco que não conduz eletricidade, como madeira ou plástico. Depois chame o socorro, 192 ou 193, e se souber, inicie os primeiros socorros.", pergunta: "Você sabe onde fica o quadro de energia do nosso setor?" },
  { categoria: "Eletricidade", tema: "Bloqueio e etiquetagem", conteudo: "Antes de manutenção ou limpeza em máquina, a energia precisa ser desligada, travada com cadeado e etiquetada com o nome de quem está trabalhando. Só quem colocou o cadeado pode tirar. Depois de bloquear, teste para ter certeza de que a máquina não liga. Esse cuidado evita que alguém religue sem saber que há uma pessoa ali.", pergunta: "Em quais máquinas daqui fazemos bloqueio antes de mexer?" },
  { categoria: "Eletricidade", tema: "Eletricidade e água", conteudo: "Água conduz eletricidade. Não use aparelhos elétricos com as mãos ou os pés molhados, e não lave com mangueira perto de tomadas, motores e quadros. Equipamentos usados em áreas molhadas precisam ser próprios para isso e protegidos por disjuntor DR. Se um equipamento molhar, desligue e só religue depois de verificado.", pergunta: "Onde aqui eletricidade e água ficam perto uma da outra?" },
  { categoria: "Eletricidade", tema: "Quadro elétrico não é armário", conteudo: "O quadro elétrico precisa ficar fechado, sinalizado e com a frente livre para ser desligado rápido em uma emergência. Não guarde materiais dentro ou na frente dele, e não deixe a porta aberta. Só pessoas autorizadas mexem dentro do quadro. Disjuntor que desarma várias vezes indica problema: não force, chame a manutenção.", pergunta: "Os nossos quadros elétricos estão fechados e com a frente livre?" },
  { categoria: "Trabalho em altura", tema: "Uso correto da escada", conteudo: "Antes de subir, confira degraus, sapatas e travas. Apoie a escada em piso firme, com a base afastada da parede cerca de um quarto da altura. Suba e desça de frente para a escada, com as mãos livres, mantendo três pontos de apoio. Nunca use o último degrau nem improvise com cadeiras, caixas ou baldes.", pergunta: "Quando foi a última vez que você viu alguém subir em algo improvisado?" },
  { categoria: "Trabalho em altura", tema: "Andaimes", conteudo: "Andaime só é montado e desmontado por pessoal treinado, com base nivelada, travamentos e guarda-corpo completo. O piso precisa ser inteiro, sem tábuas soltas ou vãos. Não suba pelo lado de fora das travessas: use a escada de acesso. Antes de usar, confira se o andaime foi liberado.", pergunta: "O que você olha antes de subir em um andaime?" },
  { categoria: "Trabalho em altura", tema: "Inspeção do cinto paraquedista", conteudo: "Antes de cada uso, confira as fitas: sem cortes, desfiados, queimaduras ou manchas de produto. Verifique fivelas, mosquetões e o absorvedor de energia. Cinto que segurou uma queda deve ser retirado de uso, mesmo que pareça bom. Guarde longe do sol e de produtos químicos.", pergunta: "Como você faria a inspeção do seu cinto agora, passo a passo?" },
  { categoria: "Trabalho em altura", tema: "Aberturas no piso e bordas", conteudo: "Buracos no piso, poços e bordas de laje sem proteção causam quedas graves. Toda abertura precisa estar fechada com tampa resistente e fixada, ou cercada por guarda-corpo. Se você precisar retirar uma proteção para trabalhar, recoloque assim que terminar. Nunca deixe uma abertura sem sinalização.", pergunta: "Tem alguma abertura ou borda aqui que precisa de proteção?" },
  { categoria: "Trabalho em altura", tema: "Telhados", conteudo: "Telhas de fibrocimento e translúcidas não aguentam o peso de uma pessoa. Trabalho em telhado exige tábuas ou passarelas de apoio, linha de vida e cinto ancorado. Não ande sobre as telhas, nem mesmo nas próximas às vigas. Em dia de chuva ou vento forte, o serviço não deve ser feito.", pergunta: "Alguém aqui já precisou subir no telhado? Como foi feito?" },
  { categoria: "Máquinas e ferramentas", tema: "Esmerilhadeira", conteudo: "A esmerilhadeira gira muito rápido e o disco pode se partir. Use o disco certo para o material e para a rotação da máquina, sempre com a proteção instalada. Segure com as duas mãos e use óculos, protetor facial e auricular. Nunca use o disco de corte para desbastar e não tire a capa de proteção.", pergunta: "Quem aqui usa esmerilhadeira e quais EPIs usa?" },
  { categoria: "Máquinas e ferramentas", tema: "Facas e utensílios cortantes", conteudo: "Faca afiada é mais segura que faca cega, porque exige menos força. Corte sempre para longe do corpo, sobre tábua firme, e use luva de malha de aço quando indicado. Não tente pegar uma faca que está caindo. Guarde em suporte próprio, nunca solta na pia ou na gaveta.", pergunta: "Onde ficam guardadas as facas no nosso setor?" },
  { categoria: "Máquinas e ferramentas", tema: "Ferramentas elétricas portáteis", conteudo: "Antes de usar, confira o cabo, o plugue e a carcaça. Desligue da tomada para trocar broca, disco ou lâmina. Não carregue a ferramenta pelo fio e não puxe o plugue pelo cabo. Ferramenta com choque, faísca ou cheiro de queimado deve sair de uso e ir para a manutenção.", pergunta: "Tem alguma ferramenta elétrica aqui com cabo emendado ou danificado?" },
  { categoria: "Máquinas e ferramentas", tema: "Masseira, cilindro e batedeira industrial", conteudo: "Essas máquinas puxam a mão e o braço em fração de segundo. Só opere com a grade ou tampa de proteção fechada e funcionando. Nunca coloque a mão dentro para empurrar massa com a máquina ligada. Para limpar, desligue e tire da tomada. Teste o botão de emergência no começo do turno.", pergunta: "O botão de emergência da nossa máquina está funcionando hoje?" },
  { categoria: "Máquinas e ferramentas", tema: "Compressores e ar comprimido", conteudo: "Ar comprimido não é brinquedo: pode penetrar na pele, estourar o tímpano e lançar partículas nos olhos. Nunca aponte o jato para pessoas e não use para limpar a roupa ou o corpo. Mangueiras e engates precisam estar em bom estado e presos. O reservatório do compressor deve ter manutenção e inspeção em dia.", pergunta: "Já viu alguém usando ar comprimido para se limpar?" },
  { categoria: "Máquinas e ferramentas", tema: "Partes móveis e roupas", conteudo: "Polias, correias, eixos e engrenagens podem prender roupas, cabelos, luvas e acessórios. Mantenha as proteções no lugar, cabelo preso e nada pendurado no corpo. Não se apoie nem estique o braço sobre máquinas em funcionamento. Se uma proteção estiver solta ou faltando, pare e avise.", pergunta: "Tem alguma proteção de máquina solta ou faltando aqui?" },
  { categoria: "Máquinas e ferramentas", tema: "Manutenção só com máquina parada", conteudo: "Limpeza, ajuste e destravamento devem ser feitos com a máquina desligada, bloqueada e com as partes paradas. Muitos acidentes acontecem na pressa de tirar um material enroscado. Aguarde a parada total e use ferramentas para alcançar, nunca as mãos.", pergunta: "O que fazemos aqui quando um material enrosca na máquina?" },
  { categoria: "Produtos químicos", tema: "Rotulagem e o símbolo de perigo", conteudo: "Os pictogramas do rótulo mostram o tipo de perigo: inflamável, corrosivo, tóxico, irritante, perigoso ao meio ambiente. Aprenda a reconhecer cada um. Todo frasco precisa estar identificado, inclusive os que você dilui. Frasco sem rótulo não deve ser usado: separe e avise.", pergunta: "Quais símbolos de perigo aparecem nos produtos que usamos?" },
  { categoria: "Produtos químicos", tema: "Ficha de segurança (FDS)", conteudo: "A ficha com dados de segurança traz tudo sobre o produto: perigos, EPIs, primeiros socorros, combate a incêndio e o que fazer em vazamento. Ela deve estar disponível perto de onde o produto é usado. Antes de usar um produto novo, leia ao menos as partes de perigos e primeiros socorros.", pergunta: "Onde ficam as fichas de segurança dos nossos produtos?" },
  { categoria: "Produtos químicos", tema: "Vazamento de produto", conteudo: "Em um vazamento, afaste as pessoas e isole a área. Se o produto for inflamável, elimine fontes de ignição. Use os EPIs indicados na FDS e contenha o produto com material absorvente, sem deixar chegar ao ralo. Descarte o material contaminado como resíduo perigoso.", pergunta: "Temos kit de contenção de vazamento? Onde fica?" },
  { categoria: "Produtos químicos", tema: "Produtos de limpeza", conteudo: "Produtos de limpeza também são químicos. Nunca misture água sanitária com amoníaco, desinfetantes ou ácidos: a mistura libera gases tóxicos. Use luva e, quando indicado, óculos. Dilua na proporção do rótulo, porque mais forte não limpa melhor e aumenta o risco.", pergunta: "Quais produtos de limpeza usamos e algum deles já irritou sua pele?" },
  { categoria: "Produtos químicos", tema: "Armazenamento de químicos", conteudo: "Produtos devem ficar em local ventilado, identificado, longe do sol e do calor, e separados por compatibilidade: ácidos longe de bases, oxidantes longe de inflamáveis. Use bacia de contenção para líquidos. Nunca guarde produto químico junto com alimentos ou em embalagem de bebida.", pergunta: "Nosso local de produtos químicos está organizado e identificado?" },
  { categoria: "Saúde e bem-estar", tema: "Sono e segurança", conteudo: "Dormir pouco diminui a atenção, os reflexos e a capacidade de decidir, como se a pessoa tivesse bebido. Quem trabalha em turno precisa cuidar ainda mais do descanso: quarto escuro, horário regular e pouco café perto da hora de dormir. Se estiver com muito sono, avise antes de operar máquinas ou dirigir.", pergunta: "Quantas horas você dormiu esta noite?" },
  { categoria: "Saúde e bem-estar", tema: "Alimentação e energia", conteudo: "Pular refeições causa tontura, irritação e falta de atenção. Faça as refeições nos horários, beba água e prefira comida de verdade a lanches ultraprocessados. No calor, refeições muito pesadas dão sono. Comer bem também é parte de trabalhar com segurança.", pergunta: "Você tomou café da manhã hoje?" },
  { categoria: "Saúde e bem-estar", tema: "Álcool, drogas e trabalho", conteudo: "Álcool e drogas diminuem a atenção e os reflexos e aumentam muito o risco de acidente. Os efeitos podem durar até o dia seguinte. Alguns remédios também dão sono: avise a liderança se estiver tomando medicação que interfira no trabalho. Pedir ajuda para lidar com dependência é um ato de coragem.", pergunta: "Você sabe se algum remédio que você toma dá sonolência?" },
  { categoria: "Saúde e bem-estar", tema: "Exames ocupacionais", conteudo: "Os exames do PCMSO acompanham a sua saúde e mostram cedo se o trabalho está afetando o corpo, como perda auditiva ou problemas respiratórios. Faça os exames nas datas marcadas e conte ao médico o que você sente. O resultado é sigiloso, e o ASO só informa se você está apto ou não para a função.", pergunta: "Quando é o seu próximo exame periódico?" },
  { categoria: "Saúde e bem-estar", tema: "Vacinação", conteudo: "Vacinas protegem você, sua família e os colegas. Algumas atividades exigem vacinas específicas, como tétano para quem pode se cortar e hepatite B para quem lida com material biológico. Mantenha a carteira de vacinação em dia e aproveite as campanhas do posto de saúde.", pergunta: "Sua vacina contra o tétano está em dia?" },
  { categoria: "Saúde e bem-estar", tema: "Proteção contra o sol", conteudo: "Quem trabalha ao ar livre está mais exposto ao câncer de pele. Use protetor solar e reaplique a cada duas horas, chapéu ou boné com proteção na nuca, roupas de manga longa e óculos com proteção UV. Evite o sol forte entre 10h e 16h sempre que possível e beba bastante água.", pergunta: "Quem aqui trabalha no sol e como está se protegendo?" },
  { categoria: "Saúde e bem-estar", tema: "Cuidado com a voz", conteudo: "Quem fala muito no trabalho, como atendentes e instrutores, precisa cuidar da voz. Beba água ao longo do dia, evite gritar e falar em ambiente muito barulhento, e faça pausas. Rouquidão que dura mais de duas semanas deve ser avaliada por um médico.", pergunta: "Você usa muito a voz no seu trabalho?" },
  { categoria: "Saúde e bem-estar", tema: "Cuidar da coluna fora do trabalho", conteudo: "A coluna é a mesma no trabalho e em casa. Levantar compras, carregar criança e fazer faxina pedem os mesmos cuidados: joelhos dobrados, carga perto do corpo e nada de torcer o tronco. Fortalecer a musculatura com caminhada e exercícios leves ajuda a prevenir dores.", pergunta: "O que você faz em casa que exige esforço da coluna?" },
  { categoria: "Comportamento seguro", tema: "Direito de recusa", conteudo: "Se você perceber um risco grave e iminente para a sua vida ou de colegas, você pode interromper a atividade e comunicar a liderança. Esse direito existe para proteger, e ninguém deve ser punido por usá-lo de boa-fé. Melhor parar e conferir do que arriscar.", pergunta: "Em que situação você pararia uma atividade por falta de segurança?" },
  { categoria: "Comportamento seguro", tema: "Excesso de confiança", conteudo: "Quem faz a mesma tarefa há muito tempo pode começar a pular etapas, achando que nada vai acontecer. É justamente aí que o acidente acontece. Faça sempre o procedimento completo, mesmo na centésima vez. Experiência é para trabalhar melhor, não para dispensar cuidados.", pergunta: "Tem algum passo de segurança que a gente costuma pular por costume?" },
  { categoria: "Comportamento seguro", tema: "Atalhos perigosos", conteudo: "Pular uma proteção, passar por baixo de uma carga ou cortar caminho por área isolada economiza segundos e pode custar uma vida. Atalho que dispensa segurança não é esperteza. Se o caminho certo é ruim, sugira uma melhoria, mas não arrisque.", pergunta: "Existe algum atalho que as pessoas costumam pegar aqui?" },
  { categoria: "Comportamento seguro", tema: "Cuidar do colega", conteudo: "Segurança é trabalho de equipe. Se você vê um colega sem EPI, distraído ou fazendo algo perigoso, fale com respeito, na hora. Ninguém se ofende com quem quer ver o outro voltar para casa inteiro. E quando alguém te alertar, agradeça.", pergunta: "Como você gostaria de ser avisado se estivesse fazendo algo arriscado?" },
  { categoria: "Comportamento seguro", tema: "Percepção de risco", conteudo: "Antes de começar qualquer tarefa, pare um minuto e pergunte: o que pode dar errado aqui? O que pode cair, prender, cortar, queimar, dar choque ou escorregar? Essa rápida avaliação muda a forma de fazer o trabalho e evita a maior parte dos acidentes.", pergunta: "Qual o risco que você identificou na sua primeira tarefa de hoje?" },
  { categoria: "Comportamento seguro", tema: "Brincadeiras no trabalho", conteudo: "Brincadeiras com empurrões, sustos, ar comprimido ou jogar objetos já causaram acidentes graves. No ambiente de trabalho, máquinas, ferramentas e produtos não perdoam distrações. Bom humor sim, brincadeira de mão não.", pergunta: "Já viu uma brincadeira que quase terminou em acidente?" },
  { categoria: "Comportamento seguro", tema: "Sinalização de segurança", conteudo: "Cada cor e placa tem um significado: vermelho para combate a incêndio e proibição, amarelo para atenção, verde para segurança e saída, azul para obrigação. Respeitar a sinalização é seguir o aviso de quem já estudou os riscos daquele local. Placa danificada ou escondida deve ser reportada.", pergunta: "Qual placa de segurança você vê no caminho até o seu posto?" },
  { categoria: "Comportamento seguro", tema: "Mudanças no trabalho", conteudo: "Máquina nova, produto novo, layout novo ou pessoa nova na equipe trazem riscos novos. Antes de começar, peça a orientação necessária e não improvise. A liderança deve avaliar os riscos de cada mudança. Se algo mudou e ninguém explicou, pergunte.", pergunta: "O que mudou recentemente no nosso trabalho?" },
  { categoria: "Trânsito e transporte", tema: "Direção defensiva", conteudo: "Dirigir de forma defensiva é prever o erro dos outros. Mantenha distância do veículo da frente, respeite a velocidade, sinalize as manobras e redobre a atenção em chuva e à noite. Celular só com o carro parado. Cinto de segurança para todos, inclusive no banco de trás.", pergunta: "Qual trecho do seu caminho até a empresa é o mais perigoso?" },
  { categoria: "Trânsito e transporte", tema: "Motociclistas", conteudo: "A moto é o veículo mais envolvido em acidentes graves no trajeto. Use capacete afivelado, jaqueta, luvas e calçado fechado. Não ande no corredor em alta velocidade e mantenha os faróis acesos. Chuva e pressa são uma combinação perigosa: saia mais cedo.", pergunta: "Quem vem de moto para o trabalho e quais cuidados toma?" },
  { categoria: "Trânsito e transporte", tema: "Carga e descarga de caminhões", conteudo: "Durante a carga e a descarga, calce as rodas do caminhão e mantenha o motor desligado. Ninguém deve ficar entre o caminhão e a doca. Organize a carga para não desabar ao abrir a porta. Use a plataforma e a rampa com cuidado e nunca suba na carroceria pelos pneus.", pergunta: "Como fazemos aqui o recebimento de mercadorias?" },
  { categoria: "Trânsito e transporte", tema: "Acidente de trajeto", conteudo: "O acidente no caminho de casa para o trabalho, e vice-versa, é considerado acidente de trabalho. Por isso, planeje o trajeto, evite pressa e respeite as regras de trânsito também como pedestre. Atravesse na faixa, olhe para os dois lados e não use fone de ouvido ao atravessar.", pergunta: "Você vem a pé, de ônibus, de carro ou de moto?" },
  { categoria: "Trânsito e transporte", tema: "Ponto cego dos veículos", conteudo: "Caminhões, ônibus e máquinas têm áreas em que o motorista não enxerga quem está ao lado ou atrás. Se você não vê o espelho do motorista, ele não vê você. Nunca passe atrás de um veículo dando ré e faça contato visual antes de cruzar na frente.", pergunta: "Onde, dentro da empresa, pessoas e veículos dividem o mesmo espaço?" },
  { categoria: "Espaço confinado", tema: "O que é espaço confinado", conteudo: "Espaço confinado é um local que não foi feito para ocupação contínua, com entrada e saída limitadas e ventilação ruim, como tanques, silos, caixas d'água, poços e galerias. O ar ali pode ter pouco oxigênio ou gases tóxicos que não têm cheiro. Ninguém entra sem permissão de entrada, medição do ar e vigia do lado de fora.", pergunta: "Temos algum espaço confinado aqui? Qual?" },
  { categoria: "Espaço confinado", tema: "Resgate em espaço confinado", conteudo: "Mais da metade das mortes em espaço confinado são de pessoas que entraram para socorrer um colega sem proteção. Se alguém passar mal lá dentro, não entre: dê o alarme e acione a equipe de resgate treinada. O vigia nunca abandona o posto e controla quem entra e quem sai.", pergunta: "Se um colega desmaiar dentro de um tanque, o que você deve fazer?" },
  { categoria: "Espaço confinado", tema: "Medição da atmosfera", conteudo: "Antes da entrada e durante todo o trabalho, o ar do espaço confinado é medido com detector de gases calibrado. Mede-se oxigênio, gases inflamáveis e gases tóxicos. Se o alarme do detector tocar, todos saem imediatamente. Nunca confie no olfato: alguns gases matam sem cheiro.", pergunta: "Você sabe ler o detector de gases que usamos?" },
  { categoria: "Meio ambiente", tema: "Economia de água", conteudo: "Água é um recurso limitado e cara para a empresa. Feche torneiras enquanto não estiver usando, avise sobre vazamentos e prefira balde a mangueira para lavar áreas. Pequenos desperdícios somados ao longo do mês fazem diferença no consumo e na conta.", pergunta: "Onde você já viu água sendo desperdiçada aqui?" },
  { categoria: "Meio ambiente", tema: "Economia de energia", conteudo: "Desligue luzes, ventiladores e equipamentos quando não estiver usando. Feche portas de câmaras frias rapidamente e não deixe geladeiras abertas. Equipamentos ligados à toa também esquentam e se desgastam mais. Economia de energia é economia para todos.", pergunta: "Qual equipamento fica ligado sem necessidade no nosso setor?" },
  { categoria: "Meio ambiente", tema: "Óleo usado de cozinha", conteudo: "Óleo de fritura jogado na pia entope o encanamento e polui a água: um litro contamina milhares de litros. Espere esfriar, guarde em garrafa fechada e entregue para a coleta ou reciclagem. Nunca descarte óleo em ralos, pias ou no lixo comum solto.", pergunta: "Como descartamos o óleo usado aqui?" },
  { categoria: "Meio ambiente", tema: "Coleta seletiva", conteudo: "Separar papel, plástico, metal e vidro do lixo orgânico facilita a reciclagem e reduz o volume que vai para o aterro. Recicláveis devem estar limpos e secos. Pilhas, baterias e lâmpadas têm descarte próprio, porque contêm metais pesados.", pergunta: "As lixeiras de coleta seletiva estão sendo usadas do jeito certo?" },
  { categoria: "Primeiros socorros", tema: "Queimaduras", conteudo: "Em queimadura, resfrie a área com água corrente em temperatura ambiente por 10 a 20 minutos. Não use pasta de dente, manteiga, pó de café ou gelo. Não estoure bolhas e não retire roupas grudadas na pele. Cubra com pano limpo e procure atendimento se a queimadura for extensa, profunda ou no rosto, mãos ou partes íntimas.", pergunta: "O que você já viu as pessoas passarem em queimaduras?" },
  { categoria: "Primeiros socorros", tema: "Cortes e sangramentos", conteudo: "Para estancar um sangramento, faça pressão direta sobre o ferimento com um pano limpo ou gaze, usando luva se possível. Se encharcar, coloque outro pano por cima sem tirar o primeiro. Eleve o membro se não houver fratura. Sangramento forte que não para precisa de socorro imediato: ligue 192.", pergunta: "Onde fica a nossa caixa de primeiros socorros?" },
  { categoria: "Primeiros socorros", tema: "Desmaio", conteudo: "Se alguém desmaiar, deite a pessoa de costas e eleve as pernas, afrouxe roupas apertadas e mantenha o local arejado. Não dê nada para beber enquanto a pessoa não estiver totalmente acordada. Se ela não acordar em poucos minutos ou não estiver respirando, ligue 192 imediatamente.", pergunta: "Alguém já presenciou um desmaio no trabalho? O que foi feito?" },
  { categoria: "Primeiros socorros", tema: "Engasgo", conteudo: "Se a pessoa não consegue falar, tossir ou respirar, faça a manobra de Heimlich: abrace por trás, coloque o punho fechado acima do umbigo e faça compressões rápidas para dentro e para cima, até o objeto sair. Se ela desmaiar, ligue 192 e inicie a reanimação. Hoje vamos simular o posicionamento das mãos.", pergunta: "Você saberia fazer a manobra de Heimlich?" },
  { categoria: "Primeiros socorros", tema: "Parada cardíaca", conteudo: "Se a pessoa não responde e não respira normalmente, ligue 192 e comece as compressões no centro do peito, com os braços esticados, forte e rápido, cerca de duas por segundo. Não pare até o socorro chegar. Se houver desfibrilador (DEA), ligue o aparelho e siga as instruções de voz.", pergunta: "Temos desfibrilador aqui? Alguém já fez o curso de reanimação?" },
  { categoria: "Primeiros socorros", tema: "Produto químico nos olhos", conteudo: "Lave imediatamente com bastante água corrente por pelo menos 15 minutos, mantendo as pálpebras abertas. Use o lava-olhos se houver. Não esfregue e não aplique colírio ou outro produto. Leve a embalagem ou a ficha de segurança do produto ao atendimento médico.", pergunta: "Onde fica o lava-olhos ou a torneira mais próxima?" },
  { categoria: "Primeiros socorros", tema: "Picadas de animais peçonhentos", conteudo: "Em picada de cobra, escorpião ou aranha, mantenha a pessoa calma e deitada, lave o local com água e sabão e leve rapidamente ao hospital. Não faça torniquete, não corte, não chupe o veneno e não passe nada no local. Se puder, fotografe o animal com segurança para ajudar no tratamento.", pergunta: "Já apareceu cobra, escorpião ou aranha aqui na empresa?" },
  { categoria: "Escritório e atendimento", tema: "Postura no computador", conteudo: "Sente-se com as costas apoiadas no encosto, os pés no chão ou no apoio e os cotovelos junto ao corpo, em ângulo reto. A parte de cima da tela fica na altura dos olhos. Teclado e mouse próximos, para não esticar os braços. A cada hora, levante e mexa o corpo.", pergunta: "Como está a altura da sua tela agora?" },
  { categoria: "Escritório e atendimento", tema: "Descanso dos olhos", conteudo: "Olhar para a tela por muito tempo cansa a vista e resseca os olhos. Use a regra 20-20-20: a cada 20 minutos, olhe para algo a cerca de 6 metros por 20 segundos. Pisque com frequência e ajuste o brilho da tela ao ambiente. Visão embaçada frequente merece consulta.", pergunta: "No fim do dia, seus olhos ficam cansados?" },
  { categoria: "Escritório e atendimento", tema: "Cadeiras e tropeços no escritório", conteudo: "No escritório também há acidentes: cadeira que escorrega, gaveta aberta, fio no chão e tapete dobrado. Feche gavetas depois de usar, organize os cabos e nunca suba em cadeira de rodinhas para alcançar algo alto. Use escada própria.", pergunta: "Tem algum fio ou objeto no caminho dos corredores do escritório?" },
  { categoria: "Escritório e atendimento", tema: "Atendimento a clientes difíceis", conteudo: "Cliente irritado não é ataque pessoal. Mantenha a calma, escute, fale em tom baixo e busque a solução dentro das regras. Se a situação ficar agressiva, chame a liderança ou a segurança e não reaja. Situações de violência ou ameaça devem ser registradas.", pergunta: "Como você lida quando um cliente está muito nervoso?" },
  { categoria: "Construção e manutenção", tema: "Escavações e valas", conteudo: "Valas profundas podem desmoronar e soterrar quem está dentro. Paredes precisam de escoramento ou inclinação adequada, e o material retirado fica afastado da borda. Tenha sempre uma escada para sair rápido. Depois de chuva, a vala deve ser inspecionada antes de entrar.", pergunta: "O que deve ser feito antes de entrar em uma vala?" },
  { categoria: "Construção e manutenção", tema: "Movimentação de cargas com guindaste ou talha", conteudo: "Nunca fique ou passe embaixo de carga suspensa. Isole a área, confira cintas, cabos e ganchos antes de içar e respeite a capacidade do equipamento. Use cordas guia para controlar a carga. Só uma pessoa treinada dá os sinais ao operador.", pergunta: "Quem é a pessoa autorizada a sinalizar para o operador de içamento?" },
  { categoria: "Construção e manutenção", tema: "Solda e corte", conteudo: "Solda produz radiação que queima a pele e os olhos, fumos tóxicos e fagulhas que provocam incêndio. Use máscara de solda com a lente correta, luvas e avental de raspa e trabalhe em local ventilado. Retire inflamáveis da área e mantenha um extintor por perto. Proteja quem está ao redor com biombos.", pergunta: "Quais cuidados com incêndio tomamos antes de soldar?" },
  { categoria: "Construção e manutenção", tema: "Perfuração de paredes", conteudo: "Antes de furar paredes e pisos, verifique se não há tubulações de água, gás ou fios elétricos passando no local. Consulte as plantas ou use detector. Use óculos e máscara contra poeira e, se o furo for em altura, siga os cuidados de trabalho em altura.", pergunta: "Como você descobre o que passa por dentro de uma parede?" },
  { categoria: "Construção e manutenção", tema: "Poeira de sílica", conteudo: "Cortar, lixar ou quebrar concreto, pedra, tijolo e granito libera poeira de sílica, que pode causar silicose, uma doença pulmonar sem cura. Use corte a úmido ou com aspiração, máscara PFF2 ou superior bem ajustada e não varra a seco: umedeça antes.", pergunta: "Em qual atividade aqui pode haver poeira de pedra ou concreto?" },
  { categoria: "Cozinha e alimentos", tema: "Fornos e superfícies quentes", conteudo: "Fornos, chapas e panelas causam queimaduras graves. Use luvas térmicas secas, porque luva molhada passa calor. Abra a porta do forno afastando o rosto do vapor. Cabos de panela virados para dentro do fogão. Avise os colegas quando estiver passando com algo quente: fale “quente, passando”.", pergunta: "Já se queimou no forno? O que aconteceu?" },
  { categoria: "Cozinha e alimentos", tema: "Fritura e óleo quente", conteudo: "Óleo quente e água não se misturam: uma gota de água faz o óleo espirrar. Seque os alimentos antes de fritar e não encha demais a fritadeira. Em caso de fogo no óleo, desligue a fonte de calor e abafe com a tampa ou use o extintor classe K. Nunca jogue água.", pergunta: "O que você faria se a fritadeira pegasse fogo?" },
  { categoria: "Cozinha e alimentos", tema: "Câmara fria", conteudo: "A câmara fria deve abrir por dentro e ter alarme. Entre com roupa térmica adequada e evite ficar muito tempo seguido: alterne com o ambiente normal. Mantenha o piso sem gelo e organize as prateleiras para não cair nada. Avise alguém sempre que entrar.", pergunta: "A porta da nossa câmara fria abre por dentro?" },
  { categoria: "Cozinha e alimentos", tema: "Higiene das mãos", conteudo: "Lavar as mãos do jeito certo previne doenças e contaminação dos alimentos. Molhe, ensaboe palmas, dorsos, entre os dedos, polegares e unhas por ao menos 20 segundos, enxágue e seque com papel. Lave sempre ao chegar, depois de ir ao banheiro, de mexer no lixo e antes de manipular alimentos.", pergunta: "Vamos treinar juntos a lavagem correta das mãos?" },
  { categoria: "Cozinha e alimentos", tema: "Fatiadores e processadores", conteudo: "Fatiador e processador cortam com facilidade dedos e mãos. Use sempre o empurrador, nunca os dedos, e mantenha a proteção no lugar. Desligue e tire da tomada para limpar, e limpe a lâmina com cuidado, de dentro para fora. Só quem foi treinado opera.", pergunta: "Quem aqui está autorizado a usar o fatiador?" },
  { categoria: "Trabalho rural", tema: "Agrotóxicos", conteudo: "Agrotóxico só é aplicado por pessoa treinada, com todos os EPIs indicados na receita e no rótulo. Respeite o intervalo de reentrada na área tratada. Não coma, beba ou fume durante a aplicação. Depois, tome banho, lave a roupa separada e devolva as embalagens vazias tríplices lavadas no local indicado.", pergunta: "Quem aqui aplica agrotóxicos e quais EPIs usa?" },
  { categoria: "Trabalho rural", tema: "Tratores e implementos", conteudo: "Tratores tombam em terrenos inclinados e próximos a valas. Use a estrutura de proteção contra capotamento com o cinto afivelado. Nunca leve carona no trator ou no implemento. Desligue a tomada de força antes de qualquer ajuste: ela pode puxar e enrolar a roupa em segundos.", pergunta: "Já viu alguém pegar carona em trator ou implemento?" },
  { categoria: "Trabalho rural", tema: "Ferramentas de corte no campo", conteudo: "Facão, foice e enxada causam cortes graves. Mantenha as ferramentas afiadas e com cabo firme, use perneira e luvas, e mantenha distância dos colegas ao trabalhar. Carregue a ferramenta com a lâmina protegida e voltada para baixo.", pergunta: "Qual a distância que mantemos entre os colegas ao usar facão?" },
  { categoria: "Trabalho rural", tema: "Calor no campo", conteudo: "No campo, o sol e o esforço físico aumentam muito o risco de mal-estar pelo calor. Beba água a cada 15 ou 20 minutos, use chapéu e roupas leves de manga longa, e faça pausas na sombra. Dor de cabeça, tontura e confusão são sinais de alerta: pare e avise.", pergunta: "Tem sombra e água fresca perto do local de trabalho hoje?" },
  { categoria: "Respeito e convivência", tema: "Diversidade e respeito", conteudo: "Cada pessoa tem sua origem, idade, crença, cor, gênero e jeito de ser. Respeitar as diferenças é parte de um ambiente seguro, em que todos se sentem à vontade para falar sobre riscos e problemas. Piadas e comentários ofensivos machucam e podem ser considerados assédio.", pergunta: "O que faz você se sentir respeitado no trabalho?" },
  { categoria: "Respeito e convivência", tema: "Comunicação clara", conteudo: "Muitos acidentes acontecem por falha de comunicação: uma instrução mal entendida ou um aviso que não chegou. Fale de forma clara, confirme se o outro entendeu e repita quando for importante. Se não entendeu, pergunte. Perguntar não é sinal de fraqueza, é sinal de cuidado.", pergunta: "Já aconteceu de uma instrução ser entendida errado aqui?" },
  { categoria: "Respeito e convivência", tema: "Conflitos no trabalho", conteudo: "Discussões e desentendimentos tiram a atenção e deixam o clima tenso, aumentando o risco de acidentes. Resolva diferenças conversando com calma, em particular, e procure a liderança se não houver acordo. Violência física ou ameaças nunca são aceitáveis.", pergunta: "O que ajuda a resolver um desentendimento entre colegas?" },
  { categoria: "Respeito e convivência", tema: "Integração de novatos", conteudo: "Quem acabou de chegar ainda não conhece os riscos, os atalhos perigosos e os procedimentos. Acolha o novato, mostre o caminho das saídas, os EPIs e os cuidados do setor. Nos primeiros dias, acompanhe de perto e incentive as perguntas. Muitos acidentes acontecem nas primeiras semanas.", pergunta: "O que você gostaria de ter sabido no seu primeiro dia aqui?" },
  { categoria: "Saúde e bem-estar", tema: "Ansiedade e pedido de ajuda", conteudo: "Todo mundo tem dias difíceis, mas preocupação constante, falta de sono, irritação e desânimo por semanas podem ser sinais de ansiedade ou depressão. Conversar com alguém de confiança e procurar o serviço de saúde faz diferença. O CVV atende de graça pelo telefone 188, 24 horas.", pergunta: "Com quem você conversa quando algo não vai bem?" },
  { categoria: "Saúde e bem-estar", tema: "Pausas que recarregam", conteudo: "Pausa não é perda de tempo: ela devolve a atenção e diminui erros. Use o intervalo para sair do posto, beber água, se alimentar e esticar o corpo. Ficar no celular o intervalo todo cansa a mente do mesmo jeito. Respeite também a pausa dos colegas.", pergunta: "O que você faz no seu intervalo para descansar de verdade?" },
  { categoria: "Saúde e bem-estar", tema: "Cansaço e jornada longa", conteudo: "Depois de muitas horas trabalhando, a atenção cai e o risco de acidente aumenta. Horas extras seguidas e falta de folga acumulam cansaço. Avise a liderança quando sentir que não está em condições de continuar com segurança, principalmente em tarefas de risco.", pergunta: "Como você percebe que está cansado demais para continuar?" },
  { categoria: "Saúde e bem-estar", tema: "Doenças transmissíveis no trabalho", conteudo: "Gripe, resfriado e outras doenças passam rápido em ambientes fechados. Cubra a boca ao tossir ou espirrar com o braço, lave as mãos com frequência e não compartilhe copos e talheres. Se estiver com febre, avise antes de vir trabalhar. Cuidar de si é cuidar dos colegas.", pergunta: "Temos álcool em gel e sabonete disponíveis nos banheiros?" },
  { categoria: "Ruído e vibração", tema: "Ruído: você está exposto?", conteudo: "Se você precisa elevar a voz para falar com alguém a um metro de distância, o ruído provavelmente está acima do limite. A exposição contínua causa perda auditiva permanente, zumbido e até irritação e cansaço. O protetor deve ser usado o tempo todo nas áreas indicadas, porque tirar por poucos minutos já reduz muito a proteção.", pergunta: "Em quais áreas daqui o barulho é mais forte?" },
  { categoria: "Ruído e vibração", tema: "Como colocar o protetor tipo plug", conteudo: "Com as mãos limpas, enrole o plug entre os dedos até ficar fino. Puxe a orelha para cima e para trás com a outra mão e coloque o plug no canal. Segure por alguns segundos até expandir. Se ficar folgado ou desconfortável, peça outro tamanho ou modelo. Vamos praticar agora.", pergunta: "Seu protetor fica bem ajustado ou sai sozinho?" },
  { categoria: "Ruído e vibração", tema: "Vibração em mãos e braços", conteudo: "Ferramentas que vibram, como marteletes, lixadeiras e motosserras, podem causar dormência, formigamento e dedos brancos com o tempo. Faça pausas, use a ferramenta adequada e com manutenção em dia, e mantenha as mãos aquecidas. Não aperte a ferramenta com mais força que o necessário.", pergunta: "Quem aqui usa ferramentas que vibram por muito tempo?" },
  { categoria: "Calor e frio", tema: "Calor intenso no ambiente", conteudo: "Fornos, caldeiras e telhados quentes deixam o ambiente muito quente. Beba água com frequência, faça pausas em local mais fresco e use roupas leves quando possível. Câimbras, tontura, confusão ou pele muito quente e seca são sinais de emergência: retire a pessoa do calor e chame socorro.", pergunta: "Temos água fresca perto dos locais mais quentes?" },
  { categoria: "Calor e frio", tema: "Choque térmico", conteudo: "Sair de um ambiente muito quente direto para um muito frio, ou o contrário, sobrecarrega o corpo. Quem alterna entre forno e câmara fria deve se agasalhar antes de entrar no frio e esperar um pouco antes de ir para o calor. Evite beber água gelada logo depois de muito esforço no calor.", pergunta: "Alguém aqui alterna entre ambiente quente e frio no mesmo turno?" },
  { categoria: "Incêndio e emergência", tema: "Extintor certo para cada fogo", conteudo: "Água (classe A) só serve para madeira, papel e tecido, nunca em eletricidade ou óleo. Pó químico (ABC ou BC) serve para líquidos inflamáveis e equipamentos elétricos. CO2 é indicado para equipamentos elétricos. Classe K é para óleo de cozinha. Leia o rótulo do extintor antes de usar.", pergunta: "Qual extintor fica mais perto do seu posto e para que tipo de fogo serve?" },
  { categoria: "Incêndio e emergência", tema: "Simulado de abandono", conteudo: "O simulado treina o corpo para agir sem pânico em uma emergência real. Participe com seriedade, siga as rotas e observe o que atrapalhou: portas travadas, corredores obstruídos, alarme que não se ouve. Depois do simulado, conte o que percebeu para a brigada.", pergunta: "No último simulado, o que funcionou e o que não funcionou?" },
  { categoria: "Incêndio e emergência", tema: "Enchentes e temporais", conteudo: "Em temporais, afaste-se de árvores, postes e estruturas metálicas e não use equipamentos ligados à tomada durante raios. Em alagamentos, não entre na água: além da correnteza, ela pode estar energizada ou contaminada. Desligue a energia de áreas alagadas antes de qualquer limpeza.", pergunta: "O que fazemos aqui quando começa uma tempestade forte?" },
  { categoria: "Máquinas e ferramentas", tema: "Empilhadeira e paleteira", conteudo: "Só opera empilhadeira quem é treinado e autorizado. Ande com os garfos baixos, respeite a velocidade e buzine nos cruzamentos. Nunca use a empilhadeira para levantar pessoas. Na paleteira manual, puxe em vez de empurrar em rampas e não ultrapasse a capacidade.", pergunta: "Quem está autorizado a operar a empilhadeira aqui?" },
  { categoria: "Máquinas e ferramentas", tema: "Caldeiras e vasos de pressão", conteudo: "Caldeiras e vasos de pressão guardam muita energia e podem explodir se mal operados. Só opera quem é habilitado. Válvulas de segurança, manômetros e inspeções periódicas precisam estar em dia. Qualquer vazamento, ruído estranho ou pressão fora do normal deve ser comunicado imediatamente.", pergunta: "Temos algum equipamento com pressão aqui? Qual?" },
  { categoria: "Máquinas e ferramentas", tema: "Ferramentas improvisadas", conteudo: "Ferramenta improvisada quebra, escapa e machuca. Não use faca como chave de fenda, alicate como martelo ou cano como alavanca. Se a ferramenta certa não está disponível, peça. Improviso não combina com segurança.", pergunta: "Qual ferramenta faz falta no nosso setor?" },
  { categoria: "Comportamento seguro", tema: "Relato de condição insegura", conteudo: "Fio desencapado, piso quebrado, proteção faltando, vazamento: toda condição insegura deve ser relatada, mesmo que pareça pequena. Quem relata ajuda a corrigir antes do acidente. Diga o que, onde e desde quando, e acompanhe se foi resolvido.", pergunta: "Qual condição insegura você relataria hoje?" },
  { categoria: "Comportamento seguro", tema: "Pare, pense e faça", conteudo: "Antes de agir, especialmente em tarefas novas ou fora da rotina, pare alguns segundos, pense nos riscos e nos passos, e só então faça. Esse momento simples evita decisões no impulso. Se algo não estiver claro, pergunte antes de começar.", pergunta: "Qual tarefa de hoje merece um minuto a mais de planejamento?" },
  { categoria: "Comportamento seguro", tema: "Distrações no trabalho", conteudo: "Conversas paralelas, celular, fone de ouvido e pensamentos longe tiram o foco da tarefa. Em atividades de risco, a atenção precisa ser total. Se alguém está operando uma máquina, espere a pausa para conversar. Se estiver preocupado com algo, divida com a liderança.", pergunta: "O que mais tira a sua atenção durante o trabalho?" },
  { categoria: "Comportamento seguro", tema: "Exemplo da liderança", conteudo: "Líder que usa EPI, segue os procedimentos e para o trabalho inseguro mostra para a equipe que segurança é prioridade. A equipe faz o que vê, não só o que ouve. E cada trabalhador também é exemplo para os novatos e os colegas.", pergunta: "Que exemplo de segurança você dá para os colegas?" },
  { categoria: "Ordem e limpeza", tema: "Armazenamento em prateleiras", conteudo: "Coloque os itens pesados nas prateleiras de baixo e os leves em cima. Não suba nas prateleiras para alcançar algo: use escada. Prateleiras devem estar fixadas na parede ou no piso, sem peso acima da capacidade. Caixas não podem ficar para fora da borda.", pergunta: "Tem alguma prateleira daqui sobrecarregada ou solta?" },
  { categoria: "Ordem e limpeza", tema: "Iluminação adequada", conteudo: "Ambiente mal iluminado esconde degraus, objetos no chão e partes de máquina. Lâmpadas queimadas, piscando ou sujas devem ser trocadas. Escadas e corredores precisam de boa iluminação. Avise a manutenção sempre que um ponto de luz não estiver funcionando.", pergunta: "Tem algum lugar aqui que fica escuro demais?" },
  { categoria: "Ergonomia", tema: "Trabalho sentado por muito tempo", conteudo: "Ficar sentado por horas também cansa: diminui a circulação nas pernas e sobrecarrega a lombar. Ajuste a cadeira, apoie bem as costas e mude de posição com frequência. A cada hora, levante, caminhe e alongue. Uma pausa curta vale mais que uma longa no fim do dia.", pergunta: "Quanto tempo você fica sentado sem levantar?" },
  { categoria: "Ergonomia", tema: "Organização do posto de trabalho", conteudo: "Os objetos que você mais usa devem ficar ao alcance das mãos, sem precisar esticar o braço, girar o tronco ou abaixar. Ajuste a altura da bancada ao seu corpo quando possível. Um posto bem organizado diminui o esforço e o cansaço.", pergunta: "O que você poderia mudar de lugar no seu posto para facilitar o trabalho?" },
  { categoria: "Produtos químicos", tema: "Inflamáveis no dia a dia", conteudo: "Álcool, gasolina, thinner, solventes e aerossóis pegam fogo com facilidade, até com uma faísca. Guarde em local ventilado, longe de calor e de tomadas, em embalagens fechadas e identificadas. Use somente a quantidade necessária para o dia. Não fume nem acenda chamas perto deles.", pergunta: "Onde guardamos produtos inflamáveis aqui?" },
  { categoria: "Construção e manutenção", tema: "Serviços de terceiros", conteudo: "Quando uma empresa terceirizada vem trabalhar aqui, os riscos dela se somam aos nossos. Antes de começar, os prestadores precisam conhecer os riscos do local, as saídas de emergência e as regras da empresa. Se notar um terceiro fazendo algo inseguro, avise a liderança.", pergunta: "Que serviço terceirizado acontece aqui com frequência?" },
  { categoria: "Respeito e convivência", tema: "Canal de denúncia e CIPA", conteudo: "A CIPA é formada por representantes dos trabalhadores e da empresa para cuidar da prevenção de acidentes e de assédio. Você pode levar a ela sugestões, condições inseguras e situações de assédio, com sigilo. Saiba quem são os membros da CIPA e como falar com eles.", pergunta: "Você sabe quem são os membros da CIPA?" },
];
